package com.abhishek.hotelbooking.repository; import com.abhishek.hotelbooking.entity.Booking; import com.abhishek.hotelbooking.enums.BookingStatus; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface BookingRepository extends JpaRepository<Booking,Long>{ List<Booking> findByUserIdOrderByIdDesc(Long userId); @Query("select count(b)>0 from Booking b where b.room.id=:roomId and b.status='CONFIRMED' and b.checkIn < :checkOut and b.checkOut > :checkIn") boolean existsOverlap(@Param("roomId") Long roomId,@Param("checkIn") LocalDate checkIn,@Param("checkOut") LocalDate checkOut); List<Booking> findByStatus(BookingStatus status); }